create temp table _rm_posts on commit drop as select id from posts where seed_batch_id = 'fm-2026-10' and author_id in (select id from _rm);
create temp table _red_before on commit drop as select (select count(*) from notifications) notifications, (select count(*) from notifications where user_id in (select id from _rm) or actor_id in (select id from _rm)) notifications_rm, (select count(*) from posts) posts, (select count(*) from replies) replies, (select count(*) from follows) follows, (select count(*) from helpful_votes) helpful_votes;

-- 1. Guards: refuse a second run, refuse anything but the live state.
do $g$ declare n bigint; begin
  select count(*) into n from profiles where seed_batch_id = 'fm-2026-10';
  if n = 29 and not exists (select 1 from profiles p join _rm on _rm.id = p.id) then
    raise exception 'batch fm-2026-10 already has 29 profiles: the cast was already cut, nothing to do';
  end if;
  if n <> 136 then raise exception 'batch fm-2026-10: expected 136 profiles, found %', n; end if;
  select count(*) into n from profiles p join (select id, handle from _rm union all select id, handle from _keep) v on v.id = p.id and v.handle = p.username where p.seed_batch_id = 'fm-2026-10';
  if n <> 136 then raise exception 'batch fm-2026-10: only % of 136 profiles have the expected id and handle', n; end if;
  select count(*) into n from profiles p join _keep k on k.id = p.id where p.role::text = k.role;
  if n <> 29 then raise exception 'batch fm-2026-10: kept profiles with an unexpected role'; end if;
  select count(*) into n from posts where seed_batch_id = 'fm-2026-10';
  if n <> 213 then raise exception 'batch fm-2026-10: expected 213 posts, found %', n; end if;
  select count(*) into n from replies where seed_batch_id = 'fm-2026-10';
  if n <> 1224 then raise exception 'batch fm-2026-10: expected 1224 replies, found %', n; end if;
  select count(*) into n from mentorships where seed_batch_id = 'fm-2026-10';
  if n <> 36 then raise exception 'batch fm-2026-10: expected 36 mentorships, found %', n; end if;
  select count(*) into n from follows where seed_batch_id = 'fm-2026-10';
  if n <> 389 then raise exception 'batch fm-2026-10: expected 389 follows, found %', n; end if;
  select count(*) into n from job_collabs where seed_batch_id = 'fm-2026-10';
  if n <> 20 then raise exception 'batch fm-2026-10: expected 20 job_collabs, found %', n; end if;
  select count(*) into n from collab_interests where seed_batch_id = 'fm-2026-10';
  if n <> 61 then raise exception 'batch fm-2026-10: expected 61 collab_interests, found %', n; end if;
  select count(*) into n from auth.users where raw_app_meta_data->>'seed_batch_id' = 'fm-2026-10' and id in (select id from _rm);
  if n <> 107 then raise exception 'batch fm-2026-10: % of 107 removed accounts have their auth user', n; end if;
  execute $q$select count(*) from posts where author_id in (select id from _rm) and seed_batch_id is distinct from 'fm-2026-10'$q$ into n;
  if n <> 0 then raise exception 'refusing to delete real members'' rows: % posts by removed accounts that aren''t seeded rows', n; end if;
  execute $q$select count(*) from replies where author_id in (select id from _rm) and seed_batch_id is distinct from 'fm-2026-10'$q$ into n;
  if n <> 0 then raise exception 'refusing to delete real members'' rows: % replies by removed accounts that aren''t seeded rows', n; end if;
  execute $q$select count(*) from replies r join _rm_posts x on x.id = r.post_id where r.seed_batch_id is distinct from 'fm-2026-10'$q$ into n;
  if n <> 0 then raise exception 'refusing to delete real members'' rows: % real replies on threads that go', n; end if;
  execute $q$select count(*) from replies r join _drop_replies d on d.id = r.id where r.seed_batch_id is distinct from 'fm-2026-10'$q$ into n;
  if n <> 0 then raise exception 'refusing to delete real members'' rows: % real replies among the replies a repair drops', n; end if;
  execute $q$select count(*) from messages where sender_id in (select id from _rm) or recipient_id in (select id from _rm)$q$ into n;
  if n <> 0 then raise exception 'refusing to delete real members'' rows: % messages to or from removed accounts', n; end if;
  execute $q$select count(*) from mentorships where (junior_id in (select id from _rm) or senior_id in (select id from _rm)) and seed_batch_id is distinct from 'fm-2026-10'$q$ into n;
  if n <> 0 then raise exception 'refusing to delete real members'' rows: % real mentorships with removed accounts', n; end if;
  execute $q$select count(*) from collab_interests ci where ci.seed_batch_id is distinct from 'fm-2026-10' and (ci.user_id in (select id from _rm) or ci.collab_id in (select id from _drop_collabs) or ci.collab_id in (select id from job_collabs where poster_id in (select id from _rm)))$q$ into n;
  if n <> 0 then raise exception 'refusing to delete real members'' rows: % real collab applications on collabs that go, or by removed accounts', n; end if;
  execute $q$select count(*) from job_collabs where poster_id in (select id from _rm) and seed_batch_id is distinct from 'fm-2026-10'$q$ into n;
  if n <> 0 then raise exception 'refusing to delete real members'' rows: % real collabs posted by removed accounts', n; end if;
  select count(*) into n from job_collabs where seed_batch_id = 'fm-2026-10' and id in (select id from _drop_collabs);
  if n <> 9 then raise exception 'batch fm-2026-10: % of 9 collabs to drop found', n; end if;
  if exists (select 1 from job_collabs where seed_batch_id = 'fm-2026-10' and poster_id in (select id from _rm) and id not in (select id from _drop_collabs)) then raise exception 'a removed account posted a collab that is not in the drop list'; end if;
  select count(*) into n from replies where seed_batch_id = 'fm-2026-10' and id in (select id from _drop_replies);
  if n <> 17 then raise exception 'batch fm-2026-10: % of 17 replies to drop found', n; end if;
  select count(*) into n from replies r join (values
    ('590990a1-4c85-50d7-90ad-f3ae44e360eb'::uuid, 'Appreciate all of this. The ride-along idea is the one I didn''t think of. Going to ask around and try to do one in each before the end of the year.'),
    ('a5652ad7-d57a-56de-9e4c-6889feff8b89'::uuid, 'Realistic if you study. Plenty of my 17-year-olds pass it. Do the practice tests until Core is boring.'),
    ('c6345d89-db21-5c3c-8221-6a3fbeb4af64'::uuid, 'update: asked to do the fittings on a repipe friday like Joy said. boss let me do the whole manifold while he watched. leaked one. fixed it. best day so far'),
    ('fa46ee7a-dd27-5c8e-a17c-03a53433a816'::uuid, 'Careful with numbers like that. A 2nd-year non-union helper at $40 an hour in Central Jersey isn''t typical. Either your buddy''s in the union and you''re hearing the total package, or he''s on a prevailing-wage job, or it''s a story. Comparing a cash rate to a union package isn''t apples to apples.'),
    ('34b3ef32-88ac-595f-8d8a-e4e3e7e91a1e'::uuid, 'Short answer as I understand it:
- Home improvement registration is for general home improvement work
- HVACR work needs the HVACR license (or working under someone who has it)
- Check with Consumer Affairs for your situation; don''t take a contractor''s word for legal stuff, including mine'),
    ('7f4a5c6f-ed24-59dc-a265-b3a9319e4a31'::uuid, 'QuickChek... ok now I know you''re all lost up there lol'),
    ('65c161fe-e92c-596a-a804-9e3f678f87ab'::uuid, '> he''s not trying to scam you

Fair. I didn''t mean he''s scamming anybody. It''s the "dead end" thing that gets me, because my weekend guy clearly isn''t one.'),
    ('a97340b3-975f-5ffa-a6be-18a92eece5c6'::uuid, 'The interview. I had real jobs to talk about the third time. Before that I had nothing.'),
    ('63a042cc-4155-5c7d-98a8-6c89a4c7bc83'::uuid, 'They knew. I said it before they could. Then I said what I did differently each year.'),
    ('9acc57e0-922b-5d67-b9af-054f1db5e4c3'::uuid, 'Will do. Thanks everyone, didn''t expect this many questions tonight.'),
    ('e6c1c703-dbca-5388-969c-229ca14b3961'::uuid, 'Mostly watching. On the electrical one he had me land a couple of breakers with the power off, after he tested it, him standing right there. Probably why I liked it lol.'),
    ('14c5b8d0-0cdd-5cc9-8f1f-732a324c18b8'::uuid, 'From what people told me, mostly about you and your work, but I am not sure. I will report back after.'),
    ('b5a7bdb8-fe22-55c7-a3c7-887e7777cb64'::uuid, 'update: had it. Mine felt like mostly questions about my work and why electrical. I talked about a service change we did in Throggs Neck and the time I mislabeled a panel. Felt okay. Now I wait again. Appreciate everyone here, and dreb especially.'),
    ('f8310562-d78f-5bf0-9762-b1545fb1acb2'::uuid, 'Same as the Bay Ridge kid. Still in school in Queens, reading all of this. There''s a Local 3 guy on here who answers everybody, so I''m getting a lot of good advice already.'),
    ('7e2fba30-3b0e-5614-806b-7d66ebbbd819'::uuid, 'This blew up lol. Thanks everybody. Short version from all of you: keep working, apply anyway, check the official site, and non-union is real too.'),
    ('974fe93f-0b26-57b0-af6b-01111492d3a7'::uuid, 'Yes. Warehouse people know how to work a shift and follow a safety rule. Get your driver''s license squared away if it isn''t, take an OSHA 10 if you can, and apply. That''s more than a lot of applicants bring.'),
    ('4a15506c-7e03-555b-80e6-9ca51ec8a4ad'::uuid, 'Not dumb. They''re usually separate; the diploma is the high school credential, and the vo-tech certificate is extra. Bring both. Check the program''s list to be sure.'),
    ('d8e81c22-fc67-5f23-a857-8b68e86a690c'::uuid, 'theres a whole thread on that one, a 164 guy asked it in the summer'),
    ('e799fe28-a476-5493-9590-f27f20fdd29d'::uuid, 'Thank you all. So: installing doesn''t need it, repairing the sealed side does, and it''s cheap enough to get anyway. Signing up for Core and Type I.'),
    ('543a0afd-5b97-550e-94f9-b1d47f20a56a'::uuid, 'Honestly it was a day of drains. The guy was great. I just didn''t light up. Maybe that''s unfair to plumbing.'),
    ('24d326d2-5958-5539-9e30-5a311005697a'::uuid, 'Not unfair. A day of drains would scare off plenty of people who''d make good plumbers. But you picked the day that felt right, and that counts for something. You can fake liking a job for a week, not for a whole career.'),
    ('bd1b9269-7de7-504c-b913-a9411a5b1e59'::uuid, 'First, follow the manufacturer''s calibration and bump-test schedule. It''s in the manual and it''s not optional. Second, a cheap meter that works beats an expensive one sitting in the truck. Third, if nobody knows when yours was last checked, assume it hasn''t been. Ask me how I know.'),
    ('37478ec8-db64-537c-8246-6da4e814f04e'::uuid, 'he said i ''broke it'' when i was looking at it lol. the gas company guy told him it had been off the chimney a while. he shut up after that'),
    ('e03b8992-e7ac-53c1-9313-71188a6f1f49'::uuid, 'Yes, you should. Electricians spend plenty of time in rooms with fuel-burning equipment, and the meter doesn''t care what trade you''re in.'),
    ('500f9330-7543-55bb-9e81-cc629eb5d543'::uuid, 'Deliveries are scheduled, usually early, with a loading area and a time slot for the hoist. On the city jobs I did back in my union days, miss your slot and you wait half a day. The city teaches you patience whether you want it or not.'),
    ('1b8ba55b-0fc2-5738-9b8d-d6d0d9e019fe'::uuid, 'Not a dumb question.
- Calling someone salaried doesn''t automatically mean no overtime
- There are rules about which jobs can be exempt, and a helper on a truck usually isn''t what people mean by that, as far as I understand it
Same answer: the Department of Labor, not me.'),
    ('4197e370-3ca8-59d9-8fa8-eba2efca8312'::uuid, 'Smaller exposure, same basic problem:
- You''re still uninsured if you fall off a ladder or break something
- "Just cleaning coils" turns into "while you''re here, can you look at this" fast
- Your boss may see it as taking his customers
Ask your boss if the shop wants the maintenance work. Usually they do, and you get the hours.'),
    ('be233b9b-3724-559d-96f0-5b2bb3997186'::uuid, 'Because some of them are. Two things:
- A lot of owners pay themselves last
- Equipment margins and service margins are very different animals
I''m not saying every owner is honest about it. I''m saying the $189 isn''t profit.'),
    ('bb9fb586-3bca-56f6-bf33-0c7acb046106'::uuid, 'Ordering the cooling towel. My boss also said nobody gets a medal for staying up there. Writing that on my tool bag.'),
    ('d76f4ac6-933c-5f86-9fc1-fff405c56e4a'::uuid, 'union city. service plumbing. hi lol, didn''t know there were this many of us'),
    ('03f5c62b-6fea-5c68-a979-6d08957109e0'::uuid, 'Kearny, right on the line with Bergen, so I claim both counties like my father did. Good to see this many of you. If any of you ever want to talk old Hudson buildings, I''ve been in most of them.'),
    ('dac7eda6-c3c4-5028-918d-bc2fa9ba3f9b'::uuid, 'more of us than I thought brother. and yes my handle says Kearny and I live in Bayonne. long story, don''t ask'),
    ('781c8970-969d-5cdf-b03f-7d5645ae0d63'::uuid, 'Honestly that''s one of the better explanations I''ve seen. Draw it: two 3-ways on the ends, the 4-way in the middle, and trace it with your finger in every position.'),
    ('2a615c67-9ce0-56fe-9187-20984ee6a507'::uuid, 'Good catch testing a fixture you''d been told was off. That''s the whole lesson. I inspect in Jersey, not the city, so I won''t speak to the NYC code, but I''ve seen a couple of these in very old houses at the shore. Same answer: rewire it, don''t patch it.'),
    ('057b4417-7e19-5746-943d-902aeffeea25'::uuid, 'Depends on the setup. A multi-zone outdoor unit usually powers its heads through the interconnect, so that''s one circuit to the outdoor unit. Three separate single-zone systems are three circuits. Follow the install manual either way.'),
    ('fdf95284-452e-5401-8c2c-43ba2011305e'::uuid, 'Lol the spaghetti question... lineset covers, run them on the back of the house, and talk about it before the install, not after. Some people hate the look of a head no matter what. Those are your ducted customers.'),
    ('808ddaa0-459b-57b8-b0d2-af5492482b48'::uuid, 'Mostly separate. On our commercial jobs it''s always a sub with its own insurance for that work. Here''s what I look for in that sub: their permits and paperwork, every time.')
  ) v(id, body) on v.id = r.id and v.body = r.body where r.seed_batch_id = 'fm-2026-10';
  if n <> 37 then raise exception 'batch fm-2026-10: only % of the 37 replies to repair still hold the seeded text', n; end if;
  select count(*) into n from posts p join (values
    ('74e792e7-756d-59ca-b879-631f095b9182'::uuid, 'A while back I posted about being 40 and unable to pick a trade. Joy suggested ride-alongs, and she''s been mentoring me since, so here''s the report.

Plumbing: a day on a repipe in an old Colonial in Metuchen. Loved the problem-solving, hated my knees by 2pm.
HVAC: a changeout in a split-level in Edison in August. The attic was brutal, but the diagnosis part was interesting.
Electrical: a service upgrade in Highland Park, panel swap, PSE&G had to come out to pull the meter. That was the one where I lost track of time.

So I''m leaning electrical, and maybe the low-voltage side later because of my knees. Two questions: did anyone else pick partly because of their body? And is it crazy to plan around knees at 40?'),
    ('2874ad19-aa79-514a-8aac-a06236f2e60b'::uuid, 'Queens kid, still in an electrical program. Local 3 is the dream but everybody knows how hard it is. My aunt lives in North Bergen and said I could stay with her after I graduate.

Dreb already told me jurisdiction is a "call them and ask" thing, which I will. But for the Jersey people: if I moved to Hudson County, would I just apply to whatever local covers there like anybody else? Is it dumb to move states for an apprenticeship? My foreman on weekends says I''m overthinking it.

edit: not trying to skip the line anywhere, just want options.'),
    ('0f26629a-2668-55c4-9db1-9e20928d3863'::uuid, 'Sorry if this has been covered. After reading the thread about what license you have when you top out, I started keeping a log. Two years at my shop now, so I already feel behind.

Right now it''s a notebook: date, job, hours, what I did. Is that enough? Do I need my boss to sign something? Should I go back and reconstruct the last two years from my pay stubs, or is that pointless? I''d rather overdo it now than find out later it''s useless.

edit: I mean for a master plumber license someday, in NJ.'),
    ('9c5f33f5-7dad-5095-8391-cd7aa070526b'::uuid, 'About 7 months in at the shop out of Bayonne. Boss says starting next week it''s boiler cleanings and fall service every day until it gets cold, mostly old one-pipe steam in Bayonne and JC, some hot water. Joy told me to ask for one new thing a week so this is me asking ahead of time.

What actually happens on a fall service for an old steam boiler? What should I be watching so I''m not just the guy holding the light? brother I''ve seen maybe three steam boilers up close.'),
    ('620e35ba-a7a2-5220-99e1-31e930bb0d5e'::uuid, 'Update from the 40-and-undecided guy. After my first round of ride-alongs I leaned electrical, but Joy said to do a second day in whatever I was least sure about, so last Saturday I went out with an HVAC shop doing boiler and furnace startups.

The HVAC day was the one where I didn''t check my phone once. Ten houses, every one different, and the tech explained everything while he worked. My knees were fine in the basements. An attic in August would probably be another story.

For people who picked HVAC: what made you sure? And is the heat-season-then-AC-season thing as brutal as it sounds?'),
    ('7a7b79c2-0486-5e0a-b82b-f7fb83780cf2'::uuid, 'Different kind of question from me. We''re finally converting our own house in Piscataway from oil to gas: split-level, oil boiler with baseboard, hot water off a tankless coil in the boiler. Got three quotes and they disagree on the chimney.

Quote 1: new gas boiler and a new gas water heater, both into the chimney with a new liner.
Quote 2: high-efficiency boiler vented out the side wall in plastic, new water heater into the existing chimney, no liner.
Quote 3: high-efficiency boiler out the side wall, a separate sidewall-vented water heater, chimney not used at all.

Quote 2 is cheapest. Quote 1''s guy says Quote 2 is going to cause problems. Who''s right, and why does the chimney matter so much? Appreciate it. Joy told me to get more than one quote, so here we are. Still doing ride-alongs too, so this is half for the house and half for me.')
  ) v(id, body) on v.id = p.id and v.body = p.body where p.seed_batch_id = 'fm-2026-10';
  if n <> 6 then raise exception 'batch fm-2026-10: only % of the 6 thread bodies to repair still hold the seeded text', n; end if;
  select count(*) into n from replies r join (values
    ('a5652ad7-d57a-56de-9e4c-6889feff8b89'::uuid, true),
    ('38be85c3-82a9-5fb3-9efd-f39719010432'::uuid, false),
    ('31afe3c5-f794-5786-8c83-a46178cb4533'::uuid, false),
    ('781c8970-969d-5cdf-b03f-7d5645ae0d63'::uuid, false),
