  if n <> 1 then raise exception 'pitch C03/JunctionBoxJunkie is not declined any more'; end if;
  select count(*) into n from collab_interests where id = 'e4a6c28b-1315-5d87-ba6f-2cc4ce8d60d6' and status::text = 'declined' and seed_batch_id = 'fm-2026-10';
  if n <> 1 then raise exception 'pitch C17/big_hector_plumb is not declined any more'; end if;
  if exists (select 1 from mentorships where id in ('05c86cf1-bc32-5fa5-9471-72bdfba3da37', 'cd7dc2b4-4f70-5e28-a0c1-d72aa0e99d25', '529d182e-67f6-5528-8dba-8dc20dfcd8ea', '1b739dde-5764-5176-8b14-0813d79415cc', 'df91e375-f6d6-52a4-89cb-4ee1ead78451', 'fa966f7e-74e6-5353-aa3c-abde56f15fd8', '4e506b82-052e-59b6-9256-5387b744e4af', 'abd7c230-854a-5e70-97c3-29fba95d508c', '0a90d4a2-a56f-56d8-ba0f-96a85ce12916', '393cad5d-8957-50a1-b1e5-d1e4cf16cc27')) then raise exception 'new mentorships already exist'; end if;
end $g$;

-- 2. Report (not refuse): real rows that go with the removed accounts. Shown again in the final summary.
create temp table _red_report on commit drop as
  select 'real follow of a removed account (dropped)'::text item, f.follower_id actor, a.username who, r.handle target, f.created_at at from follows f join _rm r on r.id = f.following_id join profiles a on a.id = f.follower_id where f.seed_batch_id is distinct from 'fm-2026-10' and a.seed_batch_id is distinct from 'fm-2026-10'
  union all select 'real follow BY a removed account (dropped)', f.follower_id, r.handle, c.username, f.created_at from follows f join _rm r on r.id = f.follower_id join profiles c on c.id = f.following_id where f.seed_batch_id is distinct from 'fm-2026-10'
  union all select 'real helpful vote on a removed reply (dropped)', v.user_id, a.username, x.username || ': ' || left(r.body, 60), v.created_at from helpful_votes v join replies r on r.id = v.reply_id join profiles a on a.id = v.user_id join profiles x on x.id = r.author_id where r.seed_batch_id = 'fm-2026-10' and (r.author_id in (select id from _rm) or r.post_id in (select id from _rm_posts) or r.id in (select id from _drop_replies))
  union all select 'real helpful vote on a removed thread (dropped)', v.user_id, a.username, p.title, v.created_at from helpful_votes v join posts p on p.id = v.post_id join profiles a on a.id = v.user_id where p.id in (select id from _rm_posts)
  union all select 'real helpful vote on kept content (kept)', v.user_id, a.username, coalesce(p.title, left(r.body, 60)), v.created_at from helpful_votes v join profiles a on a.id = v.user_id left join posts p on p.id = v.post_id left join replies r on r.id = v.reply_id where coalesce(p.seed_batch_id, r.seed_batch_id) = 'fm-2026-10' and coalesce(p.id, r.id) not in (select id from _rm_posts) and coalesce(r.author_id, p.author_id) not in (select id from _rm) and coalesce(r.post_id, '00000000-0000-0000-0000-000000000000') not in (select id from _rm_posts) and coalesce(r.id, '00000000-0000-0000-0000-000000000000') not in (select id from _drop_replies);
do $r$ declare x record; begin for x in select item, who, target from _red_report loop raise notice 'REPORT %: % -> %', x.item, x.who, x.target; end loop; end $r$;
select item, who, target, at from _red_report order by item, at;

-- 3. Delete, FK-safe: votes, pitches, collabs, follows, mentorships, replies, posts, notifications, auth users (-> profiles).
delete from helpful_votes v using replies r where v.reply_id = r.id and r.seed_batch_id = 'fm-2026-10' and (r.author_id in (select id from _rm) or r.post_id in (select id from _rm_posts) or r.id in (select id from _drop_replies));
delete from helpful_votes where post_id in (select id from _rm_posts);
delete from collab_interests where seed_batch_id = 'fm-2026-10' and (user_id in (select id from _rm) or collab_id in (select id from _drop_collabs));
delete from job_collabs where seed_batch_id = 'fm-2026-10' and id in (select id from _drop_collabs);
delete from follows where follower_id in (select id from _rm) or following_id in (select id from _rm);
delete from mentorships where seed_batch_id = 'fm-2026-10' and (junior_id in (select id from _rm) or senior_id in (select id from _rm));
delete from replies where seed_batch_id = 'fm-2026-10' and (author_id in (select id from _rm) or post_id in (select id from _rm_posts) or id in (select id from _drop_replies));
delete from posts where seed_batch_id = 'fm-2026-10' and id in (select id from _rm_posts);
delete from notifications where user_id in (select id from _rm) or actor_id in (select id from _rm);
delete from auth.users where id in (select id from _rm) and raw_app_meta_data->>'seed_batch_id' = 'fm-2026-10';

-- 4. Repair what's left: reply and thread bodies (only where the seeded text is still there), accepted answers,
--    helpful counts (as a delta from the seeded value, so real votes are kept).
update replies set body = 'Appreciate all of this. Kash, the two-year math is the part I hadn''t actually done. Going to run real numbers, and ask around about seeing each trade up close before the end of the year.' where id = '590990a1-4c85-50d7-90ad-f3ae44e360eb' and seed_batch_id = 'fm-2026-10' and body = 'Appreciate all of this. The ride-along idea is the one I didn''t think of. Going to ask around and try to do one in each before the end of the year.';  -- T03/r5
