insert into collab_interests (id, collab_id, user_id, status, note, years_experience, graduation_year, age_range, skills, is_licensed, license_note, has_own_tools, has_transport, created_at, seed_batch_id) values
  ('44d4d214-5ce1-592f-abe1-5b95ef9c4814', '06228283-7d50-5d7c-9f0f-d66b7dff824e', '3823cb41-9c6e-5a35-b2fe-2195a85f097d', 'accepted', 'ok so some context, my boss in clifton said i can take tuesday and wednesday if i want, he''d rather i see a heat pump go in on somebody else''s job before we start doing them. i''ve never done one start to finish, mostly furnaces and carrying. can i meet you at the house, and do i need anything besides hand tools?', 0, null, null, array['Heat pumps', 'Split systems']::text[], false, null, true, true, '2026-08-12T23:47:31+00:00', 'fm-2026-10'),
  ('4c389a04-ac50-53a3-8097-ce995db06afb', '363d4324-a51b-5746-a6fc-c96e1bab3fec', '70b2faae-ab2e-52c1-bf66-ddf5234d3a4a', 'accepted', 'Union City, 4 years of service, I do water heaters most weeks. Worked a Saturday for oldsteam_zig this weekend so I know the drill lol. Can meet you at the first house.', 4, null, null, array['Water heaters', 'Soldering / press fit', 'Repipes']::text[], false, null, true, true, '2026-08-17T22:41:09+00:00', 'fm-2026-10'),
  ('7e869d00-2d00-5b27-b81d-926225adfe04', 'c82e59b7-4812-537a-a43d-d289ca2de16a', '3823cb41-9c6e-5a35-b2fe-2195a85f097d', 'accepted', 'clifton, so wayne is like 15 min. helper at a small residential shop, mostly furnaces and carrying, i saw one mini split go in but i was in the truck for most of it lol. do you want me there before you start, and should i bring a notebook?', 0, null, null, array['Split systems', 'Heat pumps']::text[], false, null, true, true, '2026-08-24T23:12:46+00:00', 'fm-2026-10'),
  ('547ca834-392e-546c-ba88-dd9dba0ff467', '76c4cef0-7256-5d19-ac33-a3f600bcefea', 'f32d81a7-003f-51fe-bfbf-bf9a8f5e3ca8', 'accepted', 'cherry hill, 2 years in at a residential shop... never seen a commercial rough-in and I''d like to. 6:30 is fine, I''m about 15 minutes away. edit: I''ll bring my own level', 2, 2024, null, array['Fixture install', 'Repipes', 'Soldering / press fit']::text[], false, null, true, true, '2026-09-05T00:37:52+00:00', 'fm-2026-10'),
  ('de6e0f59-582f-5ead-89a9-b9679683d164', 'd5cddc50-e91d-5484-bfd2-8ab89d9087e9', '676c05ba-1e88-599b-baa4-e2902fae7bcd', 'accepted', 'electrician helper out of manahawkin, about a year in. mostly remodels, i''ve never seen a service upgrade start to finish. my boss said i can take monday. i have a harness. edit: i can stay tuesday too if you need', 1, null, null, array['Rough-in wiring', 'Ladder / heights work']::text[], false, null, true, true, '2026-09-16T23:20:15+00:00', 'fm-2026-10'),
  ('807d0ab9-75da-57d8-99d6-bb3daf92dbd7', 'e844addf-8cb0-5613-bf51-2cd825d207d0', '3823cb41-9c6e-5a35-b2fe-2195a85f097d', 'accepted', 'clifton again, so this one''s around the corner lol. i''ve been on a bunch of changeouts now and nobody''s ever explained how they picked the size, it''s always ''same as the old one''. does it take all day, and should i bring the notebook from the mini split day?', 0, null, null, array['Load calculations', 'Ductwork']::text[], false, null, true, true, '2026-09-14T00:18:27+00:00', 'fm-2026-10'),
  ('4888d64d-409a-526b-8193-0921f5c97077', '967e99a6-519f-5a22-a394-9ae4f8f8bb86', 'acfd4b6b-76e3-5ba1-a2a5-522d4e1a65b6', 'declined', 'bayonne, about a year as a helper, mostly old buildings, so a low basement doesn''t scare me. never touched steam, brother, and i want to. can be there before 7.', 1, null, null, array['Repipes', 'Soldering / press fit']::text[], false, null, true, true, '2026-09-19T00:05:44+00:00', 'fm-2026-10'),
  ('34411379-062b-53fb-8e7c-585e78454a84', '42668d61-a9ac-5f2d-a38f-dd82d3cac763', 'acfd4b6b-76e3-5ba1-a2a5-522d4e1a65b6', 'accepted', 'not a vo-tech grad, brother, so tell me if that rules me out. a year at a shop in bayonne, mostly demo and carrying, and i want to see how a shop that actually teaches runs. i can do the whole week.', 1, null, null, array['Repipes', 'Water heaters', 'Soldering / press fit']::text[], false, null, true, true, '2026-09-23T00:41:30+00:00', 'fm-2026-10');

